1	export interface LineItem { sku: string; unitCents: number; qty: number }
2	export function subtotal(items: LineItem[]): number {
3		return items.reduce((s, i) => s + i.unitCents * i.qty, 0);
4	}
5	/** pct is a whole percentage: applyDiscount(1000, 10) === 900. */
6	export function applyDiscount(cents: number, pct: number): number {
7		return Math.round(cents * (1 - pct));
8	}
9	export function tax(cents: number, rate = 0.08): number {
10		return Math.round(cents * rate);
11	}
